using System.Collections;
using UnityEngine;
using Photon.Pun;

public class IcePlatform : MonoBehaviourPun, ITrap
{
    [SerializeField] private PhysicMaterial iceMaterial;
    [SerializeField] private PhysicMaterial normalMaterial;
    [SerializeField] private float activationDuration = 5f;
    [SerializeField] private float slideForce = 2f;

    private Collider platformCollider;
    private bool isIcy = false;

    private void Start()
    {
        platformCollider = GetComponent<Collider>();
        if (platformCollider != null && normalMaterial != null)
        {
            platformCollider.material = normalMaterial;
        }
    }

    [PunRPC]
    public void RPC_ActivateTrap()
    {
        StartCoroutine(ActivateIce());
    }

    private IEnumerator ActivateIce()
    {
        isIcy = true;
        platformCollider.material = iceMaterial;
        yield return new WaitForSeconds(activationDuration);
        isIcy = false;
        platformCollider.material = normalMaterial;
    }

    private void OnCollisionStay(Collision collision)
    {
        if (!isIcy) return;

        Rigidbody rb = collision.rigidbody;

        Vector3 slideDirection = rb.velocity.normalized;
        if (slideDirection.magnitude > 0.1f)
        {
            rb.AddForce(slideDirection * slideForce, ForceMode.Acceleration);
        }
    }
}

using System.Collections;
using UnityEngine;
using Photon.Pun;

public class IcePlatform : MonoBehaviourPun, ITrap
{
    [SerializeField] private PhysicMaterial iceMaterial;
    [SerializeField] private PhysicMaterial normalMaterial;
    [SerializeField] private float activationDuration = 5f;

    private Collider platformCollider;

    private void Start()
    {
        platformCollider = GetComponent<Collider>();
        if (platformCollider != null && normalMaterial != null)
        {
            platformCollider.material = normalMaterial;
        }
    }

    [PunRPC]
    public void RPC_ActivateTrap()
    {
        StartCoroutine(ActivateIce());
    }

    private IEnumerator ActivateIce()
    {
        platformCollider.material = iceMaterial;
        yield return new WaitForSeconds(activationDuration);
        platformCollider.material = normalMaterial;
    }
}
